/**
 * verify-issue-body-draft — pre-`gh issue create` gate.
 *
 * Per ISSUES.yaml + LOCK_FILES memory: the agent drafts an
 * issue body in a temp file before calling `gh issue create
 * --body-file <path>`. This script validates the draft has every
 * required ISSUES §1a section + the standards-compliance reference
 * block. Exit 0 = good to submit. Non-zero = refuses; fix the draft
 * before invoking `gh`.
 *
 * Usage:
 *   node scripts/verify/verify-issue-body-draft.mjs <path/to/draft.md>
 */
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

const path = process.argv[2];
if (!path) {
  process.stderr.write(
    "usage: verify-issue-body-draft.mjs <path-to-draft.md>\n",
  );
  process.exit(2);
}

const abs = resolve(process.cwd(), path);
if (!existsSync(abs)) {
  process.stderr.write(
    `\n❌ verify-issue-body-draft: file not found: ${abs}\n`,
  );
  process.exit(1);
}

const body = readFileSync(abs, "utf-8");

const REQUIRED_SECTIONS = [
  "## Description",
  "## Acceptance criteria",
  "## Standards checklist",
  "## Technical notes",
];

const STANDARDS_BLOCK_HEADING = "## Standards compliance";

const violations = [];

for (const heading of REQUIRED_SECTIONS) {
  const pat = new RegExp(`(?:^|\\n)\\s*${escapeRegex(heading)}\\s*(?:\\n|$)`);
  if (!pat.test(body)) {
    violations.push(`missing §1a section: \`${heading}\``);
  }
}

const hasStandardsBlock = new RegExp(
  `(?:^|\\n)\\s*${escapeRegex(STANDARDS_BLOCK_HEADING)}\\s*(?:\\n|$)`,
).test(body);
if (!hasStandardsBlock) {
  violations.push(
    `missing standards-compliance reference block: \`${STANDARDS_BLOCK_HEADING}\``,
  );
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

if (violations.length === 0) {
  process.stdout.write(`✅ verify-issue-body-draft: ${path}\n`);
  process.exit(0);
}

process.stderr.write(
  `\n❌ verify-issue-body-draft: ${violations.length} violation(s) in ${path}\n`,
);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(
  "\n   Fix the body file, then re-run. NEVER `gh issue create` until this gate exits 0.\n",
);
process.exit(1);
